// ===== CONFIGURATION: the single place for store-specific values =====
// Everything below is copied onto each email item, so later nodes (classifier, agent prompt, parser, SQL) read it from there.
const STORE_NAME = 'Example Store';
const SUPPORT_EMAIL = 'support@example.com';
const STORE_URL = 'https://example.com';
const TRACKING_PAGE_URL = 'https://example.com/pages/track-your-order';   // the agent may add ?tracking=NUMBER
const ACCOUNT_URL = 'https://example.com/account';
const SIGNATURE = 'Kind regards,\nThe Example Store support team';       // end of every draft, before the AI disclosure line
const OWN_DOMAINS = ['example.com'];                                      // the store's own sending domains, no "@". Replace with yours.
const DEFAULT_LANGUAGE = 'en';                                            // ISO code. Other languages go to the "to validate" label.
const CONFIDENCE_THRESHOLD = 0.7;                                         // below this, a draft is never green (read by the prompt, the parser and the unanswered log)
const MEMORY_RETENTION_DAYS = 365;                                        // customer memory older than this is ignored and purged by Read Support Memory
// ===== END CONFIGURATION =====

// Gmail "Get Many" returns messages already parsed. Code runs once for all items: we iterate.
return $input.all().map(({ json: item }) => {
  const fromEmail = (item.from?.value?.[0]?.address || '').toLowerCase();
  const fromName = item.from?.value?.[0]?.name || '';
  const subject = item.subject || '';
  const body = (item.text || (item.textAsHtml ? item.textAsHtml.replace(/<[^>]+>/g, ' ') : '')).trim().slice(0, 8000);
  const receivedAt = item.date ? new Date(item.date).toISOString() : new Date().toISOString();
  const attachmentsList = Array.isArray(item.attachments) ? item.attachments : [];
  const attachmentMimes = attachmentsList.map(a => a.contentType || a.mime || '').filter(Boolean);
  return {
    json: {
      message_id: item.id,
      thread_id: item.threadId,
      from_email: fromEmail,
      from_name: fromName,
      subject,
      body,
      received_at: receivedAt,
      has_attachments: attachmentsList.length > 0,
      attachment_mimes: attachmentMimes,
      has_video: attachmentMimes.some(m => m.startsWith('video/')),
      store_name: STORE_NAME,
      support_email: SUPPORT_EMAIL,
      store_url: STORE_URL,
      tracking_page_url: TRACKING_PAGE_URL,
      account_url: ACCOUNT_URL,
      signature: SIGNATURE,
      own_domains: OWN_DOMAINS,
      default_language: DEFAULT_LANGUAGE,
      confidence_threshold: CONFIDENCE_THRESHOLD,
      memory_retention_days: MEMORY_RETENTION_DAYS
    }
  };
});

