// ===== CONFIGURATION =====
// Language, confidence threshold and signature come from Extract email data (single place). Everything else is here.
const ALLOWED_PROMO = new Set(['EXAMPLE10', 'EXAMPLE20']);   // codes the agent may quote without review: keep identical to the codes in your playbook (KB2)
const MAX_AUTO_DISCOUNT_PERCENT = 20;                         // a green draft quoting more is downgraded
const ESCALATION_CATEGORIES = ['chat_tool', 'reviews'];       // non-support categories forced to red when flagged upstream
const FORCE_RED_CATEGORIES = ['legal', 'safety-health', 'privacy-request'];   // categories the model may return that are always red
const FORCE_RED_EMOTIONAL_LEVEL = 4;                          // emotional_level at or above this is always red
// Deterministic detection on the customer's email, independent of the model. Case-insensitive regular expressions (as strings).
const LEGAL_PATTERNS = ['\\b(lawyer|attorney|solicitor|barrister|lawsuit|legal action|legal proceedings|small claims|take you to court|see you in court|sue you|sue the company|consumer protection (?:agency|authority|office)|trading standards|regulator)\\b'];
const SAFETY_HEALTH_PATTERNS = ['\\b(injur(?:y|ed|ies)|hospital|emergency room|ambulance|poison(?:ed|ing)?|unsafe|dangerous|hazard(?:ous)?|allergic|medical attention|my doctor|health (?:problem|issue|concern|risk)|safety (?:problem|issue|concern|risk))\\b'];
const PRIVACY_PATTERNS = ['\\b(gdpr|ccpa|data protection|personal data|personal information|right to be forgotten|data subject|erase my (?:data|account)|delete my (?:data|account|information)|copy of my (?:data|information)|access to my (?:data|information)|stop processing my|withdraw my consent)\\b'];
const AUTO_SEND_ENABLED = false;   // MASTER TOGGLE. false: every reply stays a draft for a human. Read the README before changing it.
const AUTO_SEND_CATEGORIES = new Set(['thanks-satisfaction', 'account']);
// Transparency: every customer-facing draft ends with a line saying an AI assistant was involved.
// Keyed by ISO language code; 'en' is the fallback. Add the languages you serve.
const AI_DISCLOSURE_ENABLED = true;
const AI_DISCLOSURE_DRAFT = { en: 'This reply was drafted by an AI assistant and reviewed by our team.' };   // used when a human reviews before sending
const AI_DISCLOSURE_AUTO = { en: 'This reply was written by an AI assistant.' };                             // used if you enable auto-send (nobody reviews)
// Review invitation: OFF by default. When enabled, the SAME neutral line is appended to every non-red draft,
// whatever the customer's mood or the outcome of the conversation (never filtered on satisfaction).
const REVIEW_INVITE_ENABLED = false;
const REVIEW_INVITE_TEXT = 'If you would like to share your experience of our store, you can leave a review here: https://example.com/reviews';
// ===== END CONFIGURATION =====
const asRegexes = (list) => list.map(p => new RegExp(p, 'i'));
const LEGAL_RES = asRegexes(LEGAL_PATTERNS);
const SAFETY_RES = asRegexes(SAFETY_HEALTH_PATTERNS);
const PRIVACY_RES = asRegexes(PRIVACY_PATTERNS);
const pickByLanguage = (map, lang) => map[String(lang || '').toLowerCase().slice(0, 2)] || map.en || '';
const append = (note, extra) => (note ? note + '\n\n' : '') + extra;

const inputs = $input.all();
// Use Merge Memory so that indexes line up with what the agent REALLY processed
const extractItems = $('Merge Memory').all();

return inputs.map((inp, i) => {
  const mail = extractItems[i]?.json || {};
  const DEFAULT_LANGUAGE = mail.default_language || 'en';
  const CONFIDENCE_THRESHOLD = typeof mail.confidence_threshold === 'number' ? mail.confidence_threshold : 0.7;
  const raw = inp.json.output || inp.json.text || '';
  const isMaxIterFail = /Agent stopped due to max iterations/i.test(raw);
  let parsed;
  try {
    if (isMaxIterFail) throw new Error('max iterations');
    let cleaned = raw;
    const fenced = raw.match(/```json\s*([\s\S]*?)\s*```/i);
    if (fenced) {
      cleaned = fenced[1].trim();
    } else {
      const jsonBlock = raw.match(/\{[\s\S]*\}/);
      if (jsonBlock) cleaned = jsonBlock[0];
    }
    parsed = JSON.parse(cleaned);
  } catch (e) {
    if (isMaxIterFail) {
      parsed = {
        category: 'other', emotional_level: 3, language: DEFAULT_LANGUAGE, confidence: 0.0,
        label: '🔴',
        draft_subject: 'Re: ' + (mail.subject || ''),
        draft_body: null,
        note_block: '⚠️ MAX ITERATIONS: the agent did not converge on an answer for this message.\n\n📋 CONTEXT: handle this email manually. Read it, look up the order if one is mentioned, and reply yourself.\n\n⚙️ ACTIONS TO DO (reviewer): (1) ignore the empty note draft, (2) answer the customer manually, (3) if this keeps happening on this thread, archive it to stop the loop.',
        shopify_order_number: null,
        summary: 'Agent max iterations: escalated to the reviewer',
        is_max_iter_fail: true
      };
    } else {
      parsed = {
        category: 'other', emotional_level: 2, language: DEFAULT_LANGUAGE, confidence: 0.0,
        label: '🟡',
        draft_subject: 'Re: ' + (mail.subject || ''),
        draft_body: null,
        note_block: '⚠️ TO CHECK\nReason: the agent output could not be parsed, so there is no reliable draft.\n\n📋 CONTEXT:\nFrom: ' + (mail.from_name || '') + ' <' + (mail.from_email || '') + '>\nSubject: ' + (mail.subject || '') + '\nEmail preview: ' + ((mail.body || '').slice(0, 700)) + '\n\n⚙️ ACTIONS TO DO (reviewer): read the email, check the order if one is mentioned, then write the reply manually.\n\nRaw agent output (first 500 characters):\n' + raw.slice(0, 500),
        shopify_order_number: null,
        summary: 'Agent parsing failed',
        is_max_iter_fail: false
      };
    }
  }
  if (parsed.is_max_iter_fail === undefined) parsed.is_max_iter_fail = false;
  const VALID_LABELS = new Set(['🔴', '🟡', '🔵', '🟢', 'Partnerships']);
  if (!VALID_LABELS.has(parsed.label)) {
    parsed.note_block = append(parsed.note_block, '⚠️ The label "' + parsed.label + '" is not in the list: forced to 🔵 to validate.');
    parsed.label = '🔵';
  }

  // --- DETERMINISTIC ESCALATION 1: chat tool alert / negative review ---
  // requires_support_escalation is computed upstream by Classify Non-Support Email, deterministically.
  // Reset support labels removes the urgent label that Apply Non-Support Labels put on earlier,
  // so the red label is forced here: the final label does not depend on the model.
  if (mail.requires_support_escalation === true && ESCALATION_CATEGORIES.includes(String(mail.non_support_category || '').toLowerCase())) {
    parsed.label = '\u{1F534}';
    parsed.note_block = append(parsed.note_block, '⚠️ AUTOMATIC ESCALATION: ' + (mail.escalation_reason || 'human intervention required') + '. Red label forced by the system, do not downgrade.');
  }

  // --- DETERMINISTIC ESCALATION 2: legal threat, safety or health concern, personal data request, very unhappy customer ---
  // Detected from the model's category and emotional level AND from patterns on the customer's own words.
  const clientText = (mail.subject || '') + '\n' + (mail.body || '');
  const forcedReasons = [];
  if (parsed.label !== 'Partnerships' && LEGAL_RES.some(r => r.test(clientText))) forcedReasons.push('possible legal threat');
  if (SAFETY_RES.some(r => r.test(clientText))) forcedReasons.push('possible safety or health concern');
  if (PRIVACY_RES.some(r => r.test(clientText))) forcedReasons.push('possible personal data request');
  if (FORCE_RED_CATEGORIES.includes(String(parsed.category || '').toLowerCase())) forcedReasons.push('category ' + parsed.category);
  if (Number(parsed.emotional_level) >= FORCE_RED_EMOTIONAL_LEVEL) forcedReasons.push('very unhappy customer (level ' + parsed.emotional_level + ')');
  if (forcedReasons.length > 0 && parsed.label !== '\u{1F534}') {
    parsed.label = '\u{1F534}';
    parsed.note_block = append(parsed.note_block, '⚠️ AUTOMATIC ESCALATION: ' + forcedReasons.join(', ') + '. Red label forced by the system: a human must read this email before anything is sent.');
  }

  // --- CONFIDENCE: a green draft below the threshold goes to "to validate" ---
  const conf = Number(parsed.confidence);
  if (parsed.label === '\u{1F7E2}' && !(conf >= CONFIDENCE_THRESHOLD)) {
    parsed.label = '\u{1F535}';
    parsed.note_block = append(parsed.note_block, '⚠️ LOW CONFIDENCE: the agent reported ' + (Number.isNaN(conf) ? 'no confidence value' : 'confidence ' + conf) + ', below the threshold of ' + CONFIDENCE_THRESHOLD + '. Moved to "to validate".');
  }

  // --- GUARDRAILS: prevent some cases from going out as green ---
  if (parsed.label === '\u{1F7E2}' && parsed.draft_body) {
    const bodyText = parsed.draft_body;
    const promoCodes = (bodyText.match(/\b[A-Z]{3,}\d{1,3}(?:-[A-Z0-9]+)?\b/g) || []);
    const hasUnauthorizedCode = promoCodes.some(c => !ALLOWED_PROMO.has(String(c).toUpperCase().split('-')[0]));
    const discounts = (bodyText.match(/-\s?\d{1,3}\s?%/g) || []).concat(bodyText.match(/\d{1,3}\s?%\s*(?:off|discount|reduction)/gi) || []);
    const tooHighDiscount = discounts.some(d => parseInt(String(d).replace(/\D/g, ''), 10) > MAX_AUTO_DISCOUNT_PERCENT);
    // Commitment detection: refund, reshipment/replacement, cancellation, exchange, address change. Extend for your policies.
    const refundRe = /(will (?:process|issue) (?:a|your|the) refund|we (?:will )?refund|your refund|refund (?:will be|has been|is|of\b)|refunded (?:within|in))/i;
    const replaceRe = /(replacement (?:product|item|order)|replacement of your|re-?ship|we (?:will )?(?:send|ship) (?:you )?(?:a|the|your) (?:new|replacement)|new order will be (?:re-?)?shipped)/i;
    const actionRe = /(cancel|terminat|unsubscrib|withdraw|refund|replace|re-?ship|resend|return (?:the|my|your|this|a)\b|make a return|exchange (?:the|my|your|this)|(?:change|modify)[^.]{0,25}(?:address|order|delivery|subscription))/i;
    const isEngagement = refundRe.test(bodyText) || replaceRe.test(bodyText) || actionRe.test(bodyText) || actionRe.test(clientText) || parsed.category === 'return-refund';
    if (hasUnauthorizedCode || tooHighDiscount) {
      parsed.label = '\u{1F7E1}';
      parsed.note_block = append(parsed.note_block, '⚠️ PROMO GUARDRAIL: code or discount outside what can go out without review (only the codes in ALLOWED_PROMO and discounts up to MAX_AUTO_DISCOUNT_PERCENT are accepted as green). Downgraded to yellow: the reviewer must check or create the code before sending.');
    } else if (isEngagement) {
      parsed.label = '\u{1F7E1}';
      parsed.note_block = append(parsed.note_block, '⚠️ SUPPORT GUARDRAIL: the reply contains a commitment (refund, reshipment, replacement, cancellation or change). Downgraded to yellow: the reviewer must carry out and confirm the action before sending.');
    }
  }

  // --- AUTO-SEND toggle (constants at the top) ---
  parsed.auto_send = AUTO_SEND_ENABLED && parsed.label === '\u{1F7E2}' && !!parsed.draft_body && !parsed.note_block && AUTO_SEND_CATEGORIES.has(parsed.category);

  // --- CUSTOMER-FACING FOOTER: optional neutral review line, then the AI disclosure ---
  if (parsed.draft_body) {
    if (REVIEW_INVITE_ENABLED && parsed.label !== '\u{1F534}' && parsed.label !== 'Partnerships' && REVIEW_INVITE_TEXT) {
      parsed.draft_body = parsed.draft_body + '\n\n' + REVIEW_INVITE_TEXT;
    }
    if (AI_DISCLOSURE_ENABLED) {
      const line = pickByLanguage(parsed.auto_send ? AI_DISCLOSURE_AUTO : AI_DISCLOSURE_DRAFT, parsed.language);
      if (line) parsed.draft_body = parsed.draft_body + '\n\n' + line;
    }
  }

  let assembled;
  if (parsed.draft_body) {
    assembled = parsed.note_block
      ? parsed.draft_body + '\n\n---\n[🤖 AGENT NOTE: delete before sending]\n\n' + parsed.note_block
      : parsed.draft_body;
  } else if (parsed.note_block) {
    assembled = '[🤖 AGENT NOTE]\n\n' + parsed.note_block;
  } else {
    assembled = '⚠️ The agent could not generate a reply. To be handled manually.';
  }
  return {
    json: {
      ...mail,
      ...parsed,
      assembled_body: assembled,
      is_partnership: parsed.label === 'Partnerships'
    },
    pairedItem: { item: i }
  };
});

const allMessages = $input.all().map(item => item.json || {});
const byThread = {};
for (const message of allMessages) {
  const threadId = message.threadId;
  if (!threadId) continue;
  if (!byThread[threadId]) byThread[threadId] = [];
  byThread[threadId].push(message);
}

// One run per email: the Merge node joins the support branch and the escalation branch.
const inputs = $('Merge support + escalation').all();

return inputs.map((item, index) => {
  const current = item.json || {};
  const threadMessages = byThread[current.thread_id] || [];
  const history = threadMessages
    .filter(message => message.id !== current.message_id)
    .sort((a, b) => Number(a.internalDate || 0) - Number(b.internalDate || 0))
    .slice(-5);

  const threadHistory = history.length > 0
    ? history.map(message => {
        const headers = message.payload?.headers || [];
        const fromHeader = headers.find(header => header.name === 'From');
        const fromValue = fromHeader ? fromHeader.value : (message.From || 'Unknown');
        const dateValue = message.internalDate
          ? new Date(Number(message.internalDate)).toISOString().split('T')[0]
          : '?';
        const snippet = String(message.snippet || '').slice(0, 500);
        const normalizedFrom = String(fromValue).toLowerCase();
        const ownDomains = Array.isArray(current.own_domains) ? current.own_domains : [];
        const isFromStore = ownDomains.some(d => normalizedFrom.includes(String(d).toLowerCase()));
        const speaker = isFromStore ? 'STORE (support team)' : 'CUSTOMER';
        return `[${dateValue}] ${speaker}: ${snippet}`;
      }).join('\n\n')
    : '';

  return {
    json: {
      ...current,
      thread_history: threadHistory,
      thread_history_count: history.length,
    },
    pairedItem: { item: index },
  };
});

const mailItems = $('Format Thread History').all();
const memoryItems = $input.all();

return mailItems.map((mailItem, idx) => {
  const mailData = mailItem.json;
  const memResult = memoryItems[idx]?.json;
  const hasReadableMemory = memResult && !memResult.error && memResult.customer_email;
  const memory = hasReadableMemory ? memResult : null;

  let memoryText = '';
  if (memory) {
    memoryText = 'CUSTOMER MEMORY (previous support history):\n- First contact: ' + memory.first_contact_date + '\n- Last interaction: ' + memory.last_interaction_date + '\n- Total interactions: ' + memory.total_interactions + '\n- Summary: ' + (memory.summary || 'none') + '\n- Open issues: ' + (memory.open_issues || 'none') + '\n- Sentiment history: ' + (memory.sentiment_history || 'neutral') + '\n- Last order: ' + (memory.last_order_number || 'none') + '\n- Flags: ' + (memory.flags || 'none');
  }

  return {
    json: Object.assign({}, mailData, {
      client_memory: memoryText,
      has_memory: memory !== null,
      support_memory_unavailable: !!(memResult && memResult.error)
    }),
    pairedItem: { item: idx }
  };
});

// ===== CONFIGURATION (edit this block for your own senders) =====
// Domain lists are matched on the sender domain (lower case): exact, subdomain, or substring.
// Values ending in .example are placeholders and match nothing real: replace them with the domains you see in your inbox.
// The store's own domains (OWN_DOMAINS) are set once in Extract email data.
const CHAT_TOOL_DOMAINS = ['chat-tool.example'];                  // sender domain of your live chat tool alerts
const CHAT_TOOL_ESCALATION_ENABLED = true;
// Phrases (lower case) meaning "a conversation needs a human". Matched in the subject or the body.
const CHAT_TOOL_ESCALATION_PHRASES = ['needs a human', 'human requested', 'handoff requested', 'please take over', 'agent needed'];
const REGISTRAR_DOMAINS = ['registrar.example', 'hosting.example'];            // domain and hosting providers
const FILE_TRANSFER_DOMAINS = ['file-transfer.example'];
const SOCIAL_VIDEO_DOMAINS = ['video-platform.example'];
const MESSAGING_DOMAINS = ['messaging-app.example'];                           // e.g. a messaging platform you run a business account on
const SOCIAL_ADS_DOMAINS = ['ads-manager.example', 'social-network.example'];
const SOCIAL_ADS_SENDER_NAMES = ['ads manager', 'social network'];             // exact or prefix match on the sender name (lower case)
const EMAIL_MARKETING_DOMAINS = ['email-marketing.example'];
const EMAIL_MARKETING_SENDER_NAMES = ['email marketing'];
const REVIEW_PLATFORM_DOMAINS = ['reviews.example'];
const REVIEW_PLATFORM_SENDER_NAMES = ['reviews team'];
const MARKETING_SYSTEM_DOMAINS = ['mailer.marketing.example'];                 // exact or subdomain match
const STORE_PLATFORM_DOMAINS = ['shopify.com'];                                // your shop platform: its contact form notifications are real customer email
const STORE_PLATFORM_FORM_PHRASES = ['new customer message', 'contact form', 'you received a new message from your online store'];
const NEGATIVE_REVIEW_PATTERN = /\b[123]\s*(star|stars)\b|\b[123]\s*\/\s*5\b/i;
const OOO_SUBJECT_PATTERNS = ['automatic reply', 'auto-reply', 'autoreply', 'automatic response', 'out of office', 'out-of-office', 'away from the office', 'vacation reply'];
const OOO_BODY_PATTERNS = ['i am currently out of the office', 'i will be out of the office', 'i am away until', 'i will reply when i return', 'i am on leave until', 'limited access to email', 'i will respond on my return'];
const ADMIN_KEYWORDS = ['partnership', 'collaboration', 'business proposal', 'b2b', 'commercial offer', 'meeting request', 'demo', 'investment', 'funding', 'acquisition', 'due diligence', 'cold outreach', 'account executive', 'business development', 'lead generation', 'guest post'];
const TECHNICAL_ADMIN_KEYWORDS = ['domain', 'expire', 'expiration', 'renewal', 'dns', 'ssl', 'hosting', 'registrar'];
// Words that signal a real customer. They stop the weaker "admin" rules below (not the sender-domain rules).
const SUPPORT_SIGNAL_KEYWORDS = ['order', 'parcel', 'package', 'delivery', 'tracking', 'refund', 'return', 'exchange', 'replace', 'payment', 'cancel', 'warranty', 'product', 'defective', 'faulty', 'broken', 'not working', 'damaged', 'invoice', 'account'];
const SYSTEM_ADDRESS_PATTERNS = ['no-reply', 'noreply', 'notification', 'mailer', 'donotreply', 'do-not-reply', 'newsletter', 'updates@', 'news@', 'alerts@', 'alert@', 'bounce', 'postmaster@', 'auto-', 'reply-', 'hello@', 'team@', 'info@', 'contact@', 'support@', 'service@', 'admin@', 'help@', 'feedback@'];
// Consumer mailbox providers. A sender NOT on one of these is treated as "business-like" by the weaker admin rules.
// CONSUMER_DOMAIN_STEMS matches the first label of the domain, so gmail.com, gmail.co.uk, hotmail.de, yahoo.com.au... all match.
const CONSUMER_DOMAIN_STEMS = ['gmail', 'googlemail', 'outlook', 'hotmail', 'live', 'msn', 'yahoo', 'ymail', 'icloud', 'aol', 'proton', 'protonmail', 'gmx', 'zoho'];
const CONSUMER_DOMAINS_EXACT = ['me.com', 'mac.com', 'mail.com', 'pm.me', 'fastmail.com'];
const BUSINESS_SENDER_RULES_ENABLED = true;   // false: every sender is treated as a possible customer by the weak admin rules (safer, more email reaches the agent)
// ===== END CONFIGURATION =====

return $input.all().map(({ json: mail }) => {
  const OWN_DOMAINS = Array.isArray(mail.own_domains) ? mail.own_domains : [];
  const from = (mail.from_email || '').toLowerCase();
  const fromName = (mail.from_name || '').toLowerCase();
  const subject = (mail.subject || '').toLowerCase();
  const body = (mail.body || '').toLowerCase();
  const fromDomain = from.split('@')[1] || '';
  const fromLocal = from.split('@')[0] || '';
  const domainIn = (list) => list.some(d => fromDomain === d || fromDomain.endsWith('.' + d) || fromDomain.includes(d));
  const domainIs = (list) => list.some(d => fromDomain === d || fromDomain.endsWith('.' + d));
  const nameIn = (list) => list.some(n => fromName === n || fromName.startsWith(n));

  let category = null;
  let requires_support_escalation = false;
  let escalation_reason = null;

  // ===== AUTO-ARCHIVE: out-of-office replies =====
  // Top priority: no AI agent, no draft.
  const isOOO = OOO_SUBJECT_PATTERNS.some(p => subject.includes(p)) || OOO_BODY_PATTERNS.some(p => body.slice(0, 2000).includes(p));
  if (isOOO) {
    return {
      json: Object.assign({}, mail, {
        non_support_category: 'auto_archive',
        is_non_support: true,
        requires_support_escalation: false,
        escalation_reason: null
      })
    };
  }

  const isStoreFormMail = domainIs(STORE_PLATFORM_DOMAINS) && STORE_PLATFORM_FORM_PHRASES.some(p => subject.includes(p) || body.includes(p));

  const isConsumerSender = CONSUMER_DOMAIN_STEMS.includes(fromDomain.split('.')[0]) || CONSUMER_DOMAINS_EXACT.some(d => fromDomain === d);
  const isLikelyB2BSender = BUSINESS_SENDER_RULES_ENABLED && !!fromDomain && !isConsumerSender;

  const isTechnicalAdminDomain = domainIn(REGISTRAR_DOMAINS);
  const hasTechnicalAdminKeyword = TECHNICAL_ADMIN_KEYWORDS.some(k => subject.includes(k) || body.slice(0, 1000).includes(k));
  // CUSTOMER GUARD: strong signals of a real customer. When present, the weaker rules (technical keywords,
  // admin keywords, system-looking address) do NOT file the email as admin. Rules based on the sender DOMAIN
  // (marketing tool, social platform, chat tool, reviews, file transfer, registrar) are not affected.
  const hasSupportSignal = SUPPORT_SIGNAL_KEYWORDS.some(k => subject.includes(k) || body.slice(0, 2000).includes(k)) || /#\s?\d{3,6}/.test(subject) || /#\s?\d{3,6}/.test(body.slice(0, 2000));
  const hasAdminKeyword = ADMIN_KEYWORDS.some(k => subject.includes(k) || body.slice(0, 500).includes(k));

  // ===== PRIORITY SYSTEM SENDERS =====
  // These rules come before hasSupportSignal: a system email often mentions "order" or "payment",
  // but a customer never writes from a no-reply address or from the store's own domain.
  const isOwnSender = OWN_DOMAINS.some(d => fromDomain === d || fromDomain.endsWith('.' + d));
  const isNoReplyLocal = /(^|[._-])(no[-_.]?reply|donotreply|do[-_.]not[-_.]reply|mailer-daemon|postmaster|bounces?)([._-]|$)/.test(fromLocal);
  const isMarketingSystemDomain = domainIs(MARKETING_SYSTEM_DOMAINS);

  if (isStoreFormMail) {
    category = null;
  }
  else if (isOwnSender) {
    // The store's own email received on the support inbox (newsletters, notifications sent in the store's name).
    category = 'auto_archive';
  }
  else if (isTechnicalAdminDomain) {
    category = 'admin';
  }
  else if (hasTechnicalAdminKeyword && isLikelyB2BSender && !hasSupportSignal) {
    category = 'admin';
  }
  else if (domainIn(FILE_TRANSFER_DOMAINS)) {
    category = 'file_transfer';
  }
  else if (domainIn(CHAT_TOOL_DOMAINS)) {
    // An alert saying a conversation needs a human is a real request: escalated. A routine recap does not match the phrases.
    category = 'chat_tool';
    if (CHAT_TOOL_ESCALATION_ENABLED && CHAT_TOOL_ESCALATION_PHRASES.some(p => subject.includes(p) || body.includes(p))) {
      requires_support_escalation = true;
      escalation_reason = 'Chat tool alert: a conversation needs a human';
    }
  }
  else if (domainIn(SOCIAL_VIDEO_DOMAINS)) {
    category = 'social_video';
  }
  else if (domainIn(MESSAGING_DOMAINS)) {
    category = 'messaging';
  }
  else if (domainIn(SOCIAL_ADS_DOMAINS) || nameIn(SOCIAL_ADS_SENDER_NAMES)) {
    category = 'social_ads';
  }
  else if (domainIn(EMAIL_MARKETING_DOMAINS) || nameIn(EMAIL_MARKETING_SENDER_NAMES)) {
    category = 'email_marketing';
  }
  else if (domainIn(REVIEW_PLATFORM_DOMAINS) || nameIn(REVIEW_PLATFORM_SENDER_NAMES)) {
    category = 'reviews';
    const hasNegativeReview = NEGATIVE_REVIEW_PATTERN.test(subject) || NEGATIVE_REVIEW_PATTERN.test(body.slice(0, 2000));
    if (hasNegativeReview) {
      requires_support_escalation = true;
      escalation_reason = 'Review notification with a low rating (1 to 3 stars): contact the customer privately';
    }
  }
  else if ((isNoReplyLocal && isLikelyB2BSender) || isMarketingSystemDomain) {
    // No-reply address of a service or marketing platform: never a customer.
    category = 'admin';
  }
  else if (isLikelyB2BSender && hasAdminKeyword && !hasSupportSignal) {
    category = 'admin';
  }
  else {
    const isSystemAddress = SYSTEM_ADDRESS_PATTERNS.some(p => fromLocal.includes(p) || from.includes(p));
    if (isSystemAddress && isLikelyB2BSender && !hasSupportSignal) {
      category = 'admin';
    }
  }

  return {
    json: Object.assign({}, mail, {
      non_support_category: category,
      is_non_support: category !== null,
      requires_support_escalation,
      escalation_reason
    })
  };
});

const labelMap = {
  admin: 'YOUR_LABEL_ID_ADMIN',
  file_transfer: 'YOUR_LABEL_ID_FILE_TRANSFER',
  chat_tool: 'YOUR_LABEL_ID_CHAT_TOOL',
  social_video: 'YOUR_LABEL_ID_SOCIAL_VIDEO',
  messaging: 'YOUR_LABEL_ID_MESSAGING',
  social_ads: 'YOUR_LABEL_ID_SOCIAL_ADS',
  email_marketing: 'YOUR_LABEL_ID_EMAIL_MARKETING',
  reviews: 'YOUR_LABEL_ID_REVIEWS',
  auto_archive: 'YOUR_LABEL_ID_AUTO_ARCHIVE'
};
const SUPPORT_URGENT_LABEL = 'YOUR_LABEL_ID_URGENT';

return $input.all().map(({ json: mail }, idx) => {
  const labelId = labelMap[mail.non_support_category];
  const labels = labelId ? [labelId] : [];
  if (mail.requires_support_escalation) {
    labels.push(SUPPORT_URGENT_LABEL);
  }
  return {
    json: Object.assign({}, mail, { labels_to_apply: labels }),
    pairedItem: { item: idx }
  };
});

// STRICT filter: only lets legitimate escalations through to the support flow.
// All other non-support emails stop here (non-support label already applied, log already written).
const classifyAll = $('Classify Non-Support Email').all();
const results = [];
for (const item of $input.all()) {
  const idx = item.pairedItem?.item ?? 0;
  const classifyData = classifyAll[idx]?.json;
  if (!classifyData) continue;

  // 1. Escalation flag is mandatory
  if (!classifyData.requires_support_escalation) continue;

  // 2. Category must be chat tool OR reviews
  const category = (classifyData.non_support_category || '').toLowerCase();
  if (!['chat_tool', 'reviews'].includes(category)) continue;

  // 3. Escalation reason must not be empty (at least 5 chars)
  if (!classifyData.escalation_reason || classifyData.escalation_reason.length < 5) continue;

  results.push({ json: classifyData, pairedItem: { item: idx } });
}
return results;

const CLAIM_RETENTION_DAYS = 90;   // claims older than this are purged by the same statement (the table only needs to cover the Gmail unread window)
const items = $input.all();
if (!items.length) return [{ json: { sql: "SELECT NULL::text AS message_id WHERE false;", params: [], n: 0 } }];
// Parameterized query: $1 is the retention in days, then two parameters (message_id, thread_id) per email.
const days = Math.max(1, parseInt(CLAIM_RETENTION_DAYS, 10) || 90);
const params = [days];
const rows = [];
for (const it of items) {
  params.push(String(it.json.message_id == null ? '' : it.json.message_id));
  params.push(String(it.json.thread_id == null ? '' : it.json.thread_id));
  const k = params.length;
  rows.push('($' + (k - 1) + '::text, $' + k + '::text, \'pending\', now())');
}
const sql = 'WITH purge AS (DELETE FROM support_processed WHERE processed_at < NOW() - make_interval(days => $1::int)) INSERT INTO support_processed (message_id, thread_id, label, processed_at) VALUES ' + rows.join(', ') + ' ON CONFLICT (message_id) DO NOTHING RETURNING message_id;';
return [{ json: { sql, params, n: items.length } }];

// Recovers the emails whose message_id was CLAIMED (newly inserted).
// If the claim query failed (DB down, onError continue), we degrade to NO dedup (everything goes through) so nothing is lost.
const claimRows = $input.all();
const claimFailed = claimRows.some(r => r.json && r.json.error);
const all = $('Extract email data').all();
if (claimFailed) return all;
const claimed = new Set(claimRows.map(i => i.json && i.json.message_id).filter(Boolean));
return all.filter(it => claimed.has(it.json.message_id));
